import{_ as t,o as s,c as i,a4 as n}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"1. Qu'est-ce que Teuthis-CMS ?","description":"Extrait de docs/notice-utilisateur.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"1. Qu'est-ce que Teuthis-CMS ?","description":"Extrait de docs/notice-utilisateur.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"documentation/notice/1-qu-est-ce-que-teuthis-cms.md","filePath":"documentation/notice/1-qu-est-ce-que-teuthis-cms.md"}`),a={name:"documentation/notice/1-qu-est-ce-que-teuthis-cms.md"};function o(r,e,u,l,c,d){return s(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="1-quest-ce-que-teuthis-cms-" tabindex="-1">1. Qu&#39;est-ce que Teuthis-CMS ? <a class="header-anchor" href="#1-quest-ce-que-teuthis-cms-" aria-label="Permalink to &quot;1. Qu&#39;est-ce que Teuthis-CMS ? {#1-quest-ce-que-teuthis-cms-}&quot;">​</a></h1><p>Teuthis-CMS est un logiciel de gestion de contenu (CMS) libre et gratuit, pensé pour les sites web des collectivités et administrations françaises, mais utilisable par toute organisation. Trois engagements structurent le produit :</p><ul><li><strong>Fonctionne entièrement sans intelligence artificielle.</strong> L&#39;IA est une option qu&#39;on peut activer plus tard ; aucune fonction essentielle du site n&#39;en dépend. Une instance installée sans rien configurer côté IA est pleinement opérationnelle.</li><li><strong>Rien ne se code.</strong> Créer un type de contenu (une rubrique « Actualités », un « Annuaire des services », un formulaire de demande), composer une page, gérer les droits d&#39;accès : tout se fait depuis le back-office, sans écrire une ligne de code ni faire de migration de base de données.</li><li><strong>Conçu pour la conformité française</strong> : RGPD, accessibilité numérique (déclaration générée), gestion des cookies, et une architecture pensée pour la protection des données personnelles (journalisation des accès, séparation stricte des comptes agents et des comptes usagers).</li></ul><p><strong>Le site public : un site de démarrage est livré, et il est facultatif.</strong> Teuthis-CMS fournit le moteur (l&#39;API), le back-office qui l&#39;administre et, en plus, un <strong>site de démarrage</strong> (<code>apps/front</code>, <a href="/teuthis-cms-distribution/developpeurs/adr/0047-front-de-demarrage-optionnel">ADR-0047</a>) : une application qui ne lit que l&#39;API publique, comme le ferait n&#39;importe quel site tiers, avec un thème par profil : <strong>Blog et presse</strong>, <strong>Collectivité</strong>, <strong>Portfolio</strong> et <strong>Catalogue et devis</strong>. Les quatre profils d&#39;usage qui ont un site l&#39;installent avec le CMS ; le profil « Sur mesure (headless) » s&#39;installe sans lui, pour qui construit son propre site sur l&#39;API. Il rend les pages et leurs blocs, les listes d&#39;actualités, les réalisations, albums et l&#39;équipe (Portfolio), le catalogue, la demande de devis liée à un produit, les avis et les points de vente sans carte (Catalogue et devis), l&#39;agenda (avec fichier iCal), l&#39;annuaire des élus et des lieux, les démarches en ligne, la recherche, le formulaire de contact, le bandeau de cookies, le site en plusieurs langues, le plan de site, les flux RSS et le <code>robots.txt</code>, et la page « Mes données » des abonnés ; ses polices sont servies par le site lui-même. <strong>Il ne fait pas tout</strong> : pas d&#39;espace personnel ni de connexion des usagers, pas de dépôt de pièces jointes dans les formulaires, pas de page de suivi de dossier, pas de bouton « Cette page vous a-t-elle été utile ? », pas de carte des points de vente (la recherche « les plus proches » se fait par la position du navigateur, sans service tiers), et des images servies sans déclinaisons. Son accessibilité est contrôlée automatiquement, mais aucun audit RGAA n&#39;a été fait : n&#39;en déduisez pas une conformité. Un prestataire peut remplacer ce site par le sien. Les comportements décrits plus loin du point de vue d&#39;un visiteur sont donc, selon les cas, rendus par le site de démarrage ou seulement exposés par l&#39;API : le texte le dit à chaque fois que la différence compte. Le détail du site de démarrage est dans <code>apps/front/LISEZMOI.md</code>.</p><p>Le projet est distribué sous licence libre Apache 2.0 — voir <code>LICENSE</code>.</p>',5)])])}const g=t(a,[["render",o]]);export{m as __pageData,g as default};
